class Solution {
  private static java.util.Map<String, Double> reach(
      String start, List<List<String>> pairs, double[] rates) {
    java.util.Map<String, List<Object[]>> g = new java.util.HashMap<>();
    for (int i = 0; i < pairs.size(); i++) {
      String a = pairs.get(i).get(0), b = pairs.get(i).get(1);
      g.computeIfAbsent(a, k -> new ArrayList<>()).add(new Object[] {b, rates[i]});
      g.computeIfAbsent(b, k -> new ArrayList<>()).add(new Object[] {a, 1.0 / rates[i]});
    }
    java.util.Map<String, Double> val = new java.util.HashMap<>();
    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();
    val.put(start, 1.0);
    stack.push(start);
    while (!stack.isEmpty()) {
      String u = stack.pop();
      for (Object[] e : g.getOrDefault(u, new ArrayList<>())) {
        String v = (String) e[0];
        if (!val.containsKey(v)) {
          val.put(v, val.get(u) * (double) e[1]);
          stack.push(v);
        }
      }
    }
    return val;
  }

  public double maxAmount(
      String initialCurrency,
      List<List<String>> pairs1,
      double[] rates1,
      List<List<String>> pairs2,
      double[] rates2) {
    java.util.Map<String, Double> day1 = reach(initialCurrency, pairs1, rates1);
    java.util.Map<String, Double> day2 = reach(initialCurrency, pairs2, rates2);
    double best = 1.0;
    for (java.util.Map.Entry<String, Double> e : day1.entrySet()) {
      Double back = day2.get(e.getKey());
      if (back != null) best = Math.max(best, e.getValue() / back);
    }
    return best;
  }
}
